grid=[[0]*15 for _ in range(15)]
# border rectangle rows2-10, cols3-11
for r in range(2,11):
    for c in (3,11): grid[r][c]=3
for c in range(3,12):
    grid[2][c]=3; grid[10][c]=3
grid[5][3]=3; grid[5][4]=3  # protrusion
seed=(5,4)
for r in range(3,10):
    for c in range(4,11):
        d=max(abs(r-seed[0]),abs(c-seed[1]))
        if d>0:
            grid[r][c]=4 if d%2==1 else 2
for row in grid: print(' '.join(map(str,row)))
